# -*- coding: utf-8 -*-
"""R5 step 2: full rewrite of the abstract (only words with prior-work DF >= 3) + residual terms in the body (full-window, provisional, MCP infrastructure). Usage: python ... <tex>"""
import re, sys, json, os
p = sys.argv[1]; s = open(p, encoding='utf-8').read()
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
docs = {k: v.lower() for k, v in json.load(open(os.path.join(ROOT, '30_analysis_results', 'term_review', 'prior_work_fulltext.json'), encoding='utf-8')).items()}
def df(t): t = t.lower(); return sum(1 for d in docs.values() if t in d or t.replace('-', ' ') in d)
NEW_ABSTRACT = r"""The composition of artificial-intelligence (AI) agent repositories on GitHub has not been characterized at scale. We study 9,601 public GitHub repositories with at least five stars, created between 2016 and 2025, and currently matched by eight AI-agent search queries; recursive partitioning by creation date removes the 1,000-result limit of the GitHub Search API. Because metadata are observed at a single collection time, the measured quantity is the composition of currently visible repositories by creation year. Repository clusters are derived from BGE-M3 embeddings and K-means; a rule combining silhouette with seed and bootstrap stability yields five coarse clusters (adjusted Rand index 0.97 and 0.95), whereas a solution with twelve clusters is unstable (0.63) and reported only as exploratory. Relevance was checked on a stratified sample of 404 repositories with two independent locally hosted language-model classifiers, which estimate corpus precision at 81.7\% (95\% confidence interval 77.6\% to 85.2\%); four human annotators blind to the model labels judged 120 of these repositories and estimated precision between 38\% and 92\% (majority 70\%), a range that contains the model estimate but shows poor agreement among annotators. Binomial regression with false-discovery-rate correction, complemented by alternative model specifications and by robustness checks that reweight or filter the corpus, shows that the increasing proportion of Model Context Protocol (MCP) servers and of code-generation agents and the decreasing proportion of game-related repositories are robust to model specification and to false positives at the estimated rates, whereas several declines estimated over the full period, including that of the largest orchestration cluster, are not. A change point in January--February 2023 is detected in all 30 change-point configurations and coincides with several events but is not attributed to a cause."""
s = re.sub(r'\\begin\{abstract\}.*?\\end\{abstract\}', lambda m: '\\begin{abstract}\n' + NEW_ABSTRACT + '\n\\end{abstract}', s, flags=re.S)
for pat, rep in [(r'Model Context Protocol infrastructure', 'Model Context Protocol (MCP) servers and tools'), (r'\bfull-window\b', 'full-period'), (r'\bprovisionally agent-related\b', 'agent-related by both classifiers'), (r'\bProvisional corpus precision\b', 'Estimated corpus precision'), (r'\bprovisional corpus precision\b', 'estimated corpus precision'), (r'\bprovisional\b', 'estimated'), (r'\bfull window\b', 'full period')]:
    n = len(re.findall(pat, s)); s = re.sub(pat, rep, s); print(f'{n:3d} {pat} -> {rep}')
open(p, 'w', encoding='utf-8').write(s)
ab = NEW_ABSTRACT; print('abstract words', len(ab.split()))
words = sorted(set(w for w in re.findall(r"[a-z][a-z\-]+", ab.lower()) if len(w) > 3))
low = [(w, df(w)) for w in words if df(w) < 3]; print('abstract words with DF<3:', low)
print('period DF', df('period'), '| full period', df('full period'))
